Instrument this outgoing HTTP call with an OpenTelemetry client span. Record the method, the full URL, the peer host name and port, and the response status code.

func fetchQuote(ctx context.Context, url string) (*http.Response, error) {
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	return http.DefaultClient.Do(req)
}

