```go
package main

import (
	"context"
	"net/http"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
)

func fetchQuote(ctx context.Context, url string) (*http.Response, error) {
	tracer := otel.Tracer("fetch-quote-tracer")
	ctx, span := tracer.Start(ctx, "HTTP GET "+url, trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}

	// Add semantic attributes
	span.SetAttributes(
		attribute.String("http.request.method", req.Method),
		attribute.String("url.full", req.URL.String()),
		attribute.String("server.address", req.URL.Hostname()),
		attribute.Int("server.port", func() int {
			if req.URL.Port() == "" {
				if req.URL.Scheme == "https" {
					return 443
				}
				return 80
			}
			// Parse int from port string
			var p int
			_, _ = fmt.Sscanf(req.URL.Port(), "%d", &p)
			return p
		}()),
	)

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}

	// Add response status code
	span.SetAttributes(attribute.Int("http.response.status_code", resp.StatusCode))
	if resp.StatusCode >= 400 {
		span.SetStatus(codes.Error, "HTTP request failed")
	}

	return resp, nil
}
