import { trace, SpanStatusCode } from '@opentelemetry/api';

app.get('/search', async (req, res) => {
  const tracer = trace.getTracer('my-express-tracer');

  await tracer.startActiveSpan('HTTP GET /search', async (span) => {
    try {
      // Set semantic attributes
      span.setAttribute('http.request.method', req.method);
      span.setAttribute('url.full', `${req.protocol}://${req.get('host')}${req.originalUrl}`);
      span.setAttribute('url.scheme', req.protocol);
      span.setAttribute('client.address', req.ip || req.socket.remoteAddress || '');

      const hits = await index.search(String(req.query.q));

      res.status(200).json(hits);

      span.setAttribute('http.response.status_code', 200);
      span.setStatus({ code: SpanStatusCode.OK });
    } catch (error) {
      span.setStatus({
        code: SpanStatusCode.ERROR,
        message: error instanceof Error ? error.message : 'Unknown error',
      });
      res.status(500).send('Internal Server Error');
      throw error;
    } finally {
      span.end();
    }
  });
});
