import { context, trace, SpanKind, SpanStatusCode } from '@opentelemetry/api';
import { SemanticAttributes } from '@opentelemetry/semantic-conventions';

await consumer.run({
  eachMessage: async ({ topic, partition, message }) => {
    const tracer = trace.getTracer('kafkajs-instrumentation');

    // Semantic conventions for Messaging
    const span = tracer.startSpan(`process ${topic}`, {
      kind: SpanKind.CONSUMER,
      attributes: {
        'messaging.system': 'kafka',
        'messaging.destination': topic,
        'messaging.destination_kind': 'topic',
        'messaging.kafka.partition': partition,
        'messaging.message_id': message.offset,
        'messaging.kafka.consumer_group': groupId, // ensure groupId is available in scope
      },
    });

    await context.with(trace.setSpan(context.active(), span), async () => {
      try {
        await handle(message.value);
        span.setStatus({ code: SpanStatusCode.OK });
      } catch (error) {
        span.recordException(error as Error);
        span.setStatus({
          code: SpanStatusCode.ERROR,
          message: (error as Error).message,
        });
        throw error;
      } finally {
        span.end();
      }
    });
  },
});
