```go
package middleware

import (
	"net/http"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
)

var (
	meter = otel.Meter("http-middleware")

	// Server Request Duration
	serverDuration, _ = meter.Float64Histogram(
		"http.server.request.duration",
		metric.WithDescription("Duration of HTTP server requests"),
		metric.WithUnit("s"),
	)

	// Client Request Duration
	clientDuration, _ = meter.Float64Histogram(
		"http.client.request.duration",
		metric.WithDescription("Duration of HTTP client requests"),
		metric.WithUnit("s"),
	)
)

func Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()

		// Wrap the writer to capture status code if needed, 
		// here we record the duration of the server request
		defer func() {
			duration := time.Since(start).Seconds()
			attrs := metric.WithAttributes(
				attribute.String("http.request.method", r.Method),
				attribute.String("url.scheme", r.URL.Scheme),
			)
			serverDuration.Record(r.Context(), duration, attrs)
		}()

		next.ServeHTTP(w, r)
	})
}

// Example of how to use the client histogram in an outgoing call
func TrackClientRequest(next http.RoundTripper) http.RoundTripper {
	return roundTripperFunc(func(r *http.Request) (*http.Response, error) {
		start := time.Now()
		resp, err := next.RoundTrip(r)

		duration := time.Since(start).Seconds()
		attrs := metric.WithAttributes(
			attribute.String("http.request.method", r.Method),
			attribute.String("server.address", r.URL.Hostname()),
		)
		clientDuration.Record(r.Context(), duration, attrs)

		return resp, err
	})
}

type roundTripperFunc func(*http.Request) (*http.Response, error)

func (f roundTripperFunc) RoundTrip(r *http.Request) (*http.Response, error) {
	return f(r)
}
```

