func charge(ctx context.Context, c *http.Client, body io.Reader) (*http.Response, error) {
	tracer := otel.Tracer("my-service")
	ctx, span := tracer.Start(ctx, "HTTP POST /charge", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	// Set semantic convention attributes
	span.SetAttributes(
		attribute.String("rpc.system", "http"),
		attribute.String("server.address", "payments"),
		attribute.Int("server.port", 8080),
		attribute.String("http.request.method", "POST"),
		attribute.String("peer.service", "payments"),
	)

	req, err := http.NewRequestWithContext(ctx, "POST", "http://payments:8080/charge", body)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")

	// Inject context for distributed tracing
	otel.GetTextMapPropagator().Inject(ctx, propagation.HeaderCarrier(req.Header))

	resp, err := c.Do(req)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}

	span.SetAttributes(attribute.Int("http.response.status_code", resp.StatusCode))
	if resp.StatusCode >= 400 {
		span.SetStatus(codes.Error, "http error")
	}

	return resp, nil
}
